// ── Helpers ──────────────────────────────────────────────────────────────────

/** Obtiene una pregunta por ID. Devuelve undefined si no existe. */
export function getQuestionById(id: string): BankQuestion | undefined {
  return QUESTIONS_BANK.find(q => q.id === id);
}

/** Filtra preguntas por avatar y franja horaria. */
export function getQuestionsForSlot(
  avatar: AvatarKey,
  timeSlot: TimeWindow,
): BankQuestion[] {
  return QUESTIONS_BANK.filter(q => q.avatar === avatar && q.timeSlot === timeSlot);
}
